public class Main {
    static int compute(int num) {
        if (num <= 1) {
            return num;
        }
        return compute(num - 1) + compute(num - 3);
    }

    public static void main(String[] args) {
        System.out.print(compute(5));
    }
}

class A {
    int a;
    private int b;
    protected int c;

    A(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    int func() {
        return a + b + c;
    }
}

class B extends A {
    B(int a, int b, int c) {
        super(a, b, c);
    }

    @Override
    public int func() {
        return a * c;
    }
}

public class Main {
    public static void main(String[] args) {
        A a = new A(1, 5, 3);
        B b = new B(10, 30, 50);
        System.out.print(a.func() + b.func());
    }
